/** Gallery search: the query must appear in the name, description or sites. */
export function searchGallery(query: string): GalleryScript[] {
  const q = query.trim().toLowerCase()
  return GALLERY.filter(
    (s) => !q || `${s.name} ${s.description} ${s.sites}`.toLowerCase().includes(q),
  )
}

export const QUERY = 'github'
export const MATCHES = searchGallery(QUERY)
export const PICK = MATCHES[0]

