export type RunState = 'error' | 'ran' | 'reload' | 'off' | 'paused' | 'setup'

/** A recorded run wins over the current toggle; the page keeps the copy that already ran. */
export function deriveRunState(
  enabled: boolean,
  ran: boolean,
  globalEnabled: boolean,
  operational: boolean,
): RunState {
  if (ran) return 'ran'
  if (!globalEnabled) return 'paused'
  if (!enabled) return 'off'
  if (!operational) return 'setup'
  return 'reload'
}

export function needsReload(
  enabled: boolean,
  ran: boolean,
  state: RunState,
  globalEnabled: boolean,
) {
  if (state === 'reload') return true
  return ran && (!enabled || !globalEnabled)
}

export function formatDuration(ms: number): string {
  if (ms < 1) return '<1 ms'
  return ms < 1000 ? `${ms} ms` : `${(ms / 1000).toFixed(1)} s`
}

/** Sample run recorded by the page after reload. */
export const RUN = { durationMs: 2, ago: 'now' }

export const STATE_LABEL: Record<RunState, string> = {
  ran: 'Ran',
  error: 'Error',
  reload: 'Not run yet',
  off: 'Off',
  paused: 'Paused',
  setup: 'Needs setup',
}

export const BEFORE_RELOAD = deriveRunState(true, false, true, true)
export const AFTER_RELOAD = deriveRunState(true, true, true, true)
export const AFTER_PAUSE = deriveRunState(true, true, false, true)
export const PAUSE_NEEDS_RELOAD = needsReload(true, true, AFTER_PAUSE, false)

export const RAN_LINE = `Ran ${RUN.ago} · ${formatDuration(RUN.durationMs)}`

